import * as THREE from 'three/webgpu';
import {
  uv,
  color,
  mix,
  smoothstep,
  float,
  dot,
  normalView,
  positionViewDirection,
  pow,
  sub,
  mul,
  clamp,
} from 'three/tsl';
import gsap from 'gsap';
import { createMSDFText } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'nova-atelier-glass-prism-refraction';

  // ---- scene placement -----------------------------------------------
  const scenePos = config.scenePosition || {};
  const px = scenePos.x ?? config.position?.x ?? 0;
  const py = scenePos.y ?? config.position?.y ?? 0;
  const pz = scenePos.z ?? config.position?.z ?? 0;
  group.position.set(px, py, pz);

  const rot = scenePos.rotationXYZ || config.rotation || { x: 0, y: 0, z: 0 };
  group.rotation.set(rot.x ?? 0, rot.y ?? 0, rot.z ?? 0);

  const scl = scenePos.scaleXYZ || config.scale || { x: 1, y: 1, z: 1 };
  group.scale.set(scl.x ?? 1, scl.y ?? 1, scl.z ?? 1);

  const disposables = { geometries: [], materials: [], lights: [] };
  const timelines = [];

  // ---- prism geometry ---------------------------------------------------
  // equilateral triangular cross-section, side length 1.2, length 1.8,
  // axis built horizontal (X), then tilted 12deg z / 20deg y as requested.
  const triangleSide = 1.2;
  const circumradius = triangleSide / Math.sqrt(3);
  const prismLength = 1.8;

  const prismGeometry = new THREE.CylinderGeometry(
    circumradius,
    circumradius,
    prismLength,
    3,
    1,
    false
  );
  prismGeometry.rotateZ(Math.PI / 2); // align cylinder-height axis to X (horizontal)
  disposables.geometries.push(prismGeometry);

  const prismMaterial = new THREE.MeshPhysicalNodeMaterial({
    color: 0xffffff,
    metalness: 0.0,
    roughness: 0.08,
    transmission: 1.0,
    thickness: 0.9,
    ior: 1.55,
    dispersion: 0.18,
    iridescence: 1.0,
    iridescenceIOR: 1.3,
    iridescenceThicknessRange: [120, 480],
    clearcoat: 0.25,
    clearcoatRoughness: 0.1,
    attenuationColor: new THREE.Color('#e8ecf2'),
    attenuationDistance: 2.5,
  });
  disposables.materials.push(prismMaterial);

  const prismMesh = new THREE.Mesh(prismGeometry, prismMaterial);
  prismMesh.rotation.set(
    0,
    THREE.MathUtils.degToRad(20),
    THREE.MathUtils.degToRad(12)
  );
  prismMesh.position.set(0, 0, 0);
  group.add(prismMesh);

  // ---- fresnel rim shell (TSL) -------------------------------------
  // duplicate the prism silhouette, backside additive, view-angle glow —
  // gives the "back rim carries a bright edge line" read without a flat
  // glassmorphism border trick.
  const rimGeometry = prismGeometry.clone();
  disposables.geometries.push(rimGeometry);

  const facing = clamp(dot(normalView, positionViewDirection), float(0.0), float(1.0));
  const rimFactor = pow(sub(float(1.0), facing), float(2.2));

  const rimMaterial = new THREE.MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false,
    side: THREE.BackSide,
    blending: THREE.AdditiveBlending,
  });
  rimMaterial.colorNode = mix(color('#cfe8ff'), color('#ffffff'), mul(rimFactor, float(0.4)));
  rimMaterial.opacityNode = mul(rimFactor, float(0.85));
  disposables.materials.push(rimMaterial);

  const rimMesh = new THREE.Mesh(rimGeometry, rimMaterial);
  rimMesh.scale.setScalar(1.04);
  prismMesh.add(rimMesh);

  // ---- emissive core -------------------------------------------------
  const coreGeometry = new THREE.OctahedronGeometry(0.35, 0);
  disposables.geometries.push(coreGeometry);

  const coreMaterial = new THREE.MeshStandardNodeMaterial({
    color: new THREE.Color('#ff2a38'),
    emissive: new THREE.Color('#ff2a38'),
    emissiveIntensity: 2.2, // kept under the 2.5 AgX red-clip ceiling
    roughness: 0.3,
    metalness: 0.1,
  });
  disposables.materials.push(coreMaterial);

  const coreMesh = new THREE.Mesh(coreGeometry, coreMaterial);
  coreMesh.position.set(0, 0, 0);
  prismMesh.add(coreMesh);

  // ---- back rim light (strong, cool, behind-left) --------------------
  const backRimLight = new THREE.DirectionalLight(new THREE.Color('#9fb0c4'), 3.2);
  backRimLight.position.set(-3.2, 1.4, -3.6);
  backRimLight.target.position.set(0, 0, 0);
  group.add(backRimLight);
  group.add(backRimLight.target);
  disposables.lights.push(backRimLight);

  // ---- caustic streak on the floor (engineered gradient, TSL) -------
  const causticGeometry = new THREE.PlaneGeometry(2.4, 0.5, 1, 1);
  disposables.geometries.push(causticGeometry);

  const uNode = uv().x;
  const vNode = uv().y;
  const stopA = color('#ff2a38');
  const stopB = color('#e8ecf2');
  const stopC = color('#9fb0c4');
  const gradientAB = mix(stopA, stopB, smoothstep(float(0.2), float(0.5), uNode));
  const gradientColor = mix(gradientAB, stopC, smoothstep(float(0.5), float(0.8), uNode));

  const edgeFadeX = mul(
    smoothstep(float(0.0), float(0.12), uNode),
    smoothstep(float(1.0), float(0.88), uNode)
  );
  const edgeFadeY = mul(
    smoothstep(float(0.0), float(0.4), vNode),
    smoothstep(float(1.0), float(0.6), vNode)
  );

  const causticMaterial = new THREE.MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false,
    side: THREE.DoubleSide,
  });
  causticMaterial.colorNode = gradientColor;
  causticMaterial.opacityNode = mul(mul(edgeFadeX, edgeFadeY), float(0.35));
  disposables.materials.push(causticMaterial);

  const causticMesh = new THREE.Mesh(causticGeometry, causticMaterial);
  causticMesh.rotation.x = -Math.PI / 2;
  causticMesh.position.set(0, -1.1, 0.1);
  group.add(causticMesh);

  // ---- text: headline + caption via MSDF font atlas -------------------
  const textContent = Array.isArray(config.textContent) ? config.textContent : [];
  const headlineEntry =
    textContent.find((t) => t.role === 'headline') || {
      text: 'Light, machined.',
      role: 'headline',
    };
  const captionEntry =
    textContent.find((t) => t.role === 'caption') || {
      text: 'SAPPHIRE OVER DIAL / ZERO DISTORTION',
      role: 'caption',
    };

  const headlineMesh = createMSDFText({
    text: headlineEntry.text,
    font: ctx.fontAtlas,
    fontSize: 0.34,
    color: new THREE.Color('#e8ecf2'),
    letterSpacing: -0.005,
    lineHeight: 1.1,
    anchorX: 'center',
    anchorY: 'middle',
  });
  headlineMesh.position.set(0, -1.75, 0.4);
  group.add(headlineMesh);

  const captionMesh = createMSDFText({
    text: captionEntry.text,
    font: ctx.fontAtlas,
    fontSize: 0.09,
    color: new THREE.Color('#ff2a38'),
    letterSpacing: 0.08,
    lineHeight: 1.4,
    anchorX: 'center',
    anchorY: 'middle',
  });
  captionMesh.position.set(0, -2.25, 0.4);
  group.add(captionMesh);

  // ---- cinematic primitives (never inline primitive logic) ----------
  const primitiveRefs = Array.isArray(config.cinematicPrimitives)
    ? config.cinematicPrimitives
    : [];
  primitiveRefs.forEach((primitive) => {
    const primitiveFn = ctx.primitives && ctx.primitives[primitive.name];
    if (typeof primitiveFn === 'function') {
      primitiveFn(group, primitive.params || {});
    }
  });

  // ---- extra hover flourishes layered on top of userData.handlers ----
  // caustic streak elongates ~8% on hover; on release the prism performs
  // the named "weighted-settle" preset (1.04 -> 1.0, power4.out, 0.9s).
  group.userData.handlers = group.userData.handlers || {};
  const existingOnPointerOver = group.userData.handlers.onPointerOver;
  const existingOnPointerOut = group.userData.handlers.onPointerOut;

  const causticHoverTl = gsap.timeline({ paused: true });
  causticHoverTl.to(
    causticMesh.scale,
    { x: 1.08, duration: 0.35, ease: 'power2.out' },
    0
  );
  timelines.push(causticHoverTl);

  const settleTl = gsap.timeline({ paused: true });
  settleTl.fromTo(
    prismMesh.scale,
    { x: 1.04, y: 1.04, z: 1.04 },
    { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }
  );
  timelines.push(settleTl);

  group.userData.handlers.onPointerOver = (event) => {
    causticHoverTl.play();
    if (typeof existingOnPointerOver === 'function') existingOnPointerOver(event);
  };

  group.userData.handlers.onPointerOut = (event) => {
    causticHoverTl.reverse();
    settleTl.restart();
    if (typeof existingOnPointerOut === 'function') existingOnPointerOut(event);
  };

  // ---- cleanup ---------------------------------------------------------
  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());

    disposables.geometries.forEach((g) => g && g.dispose());
    disposables.materials.forEach((m) => m && m.dispose());

    [headlineMesh, captionMesh].forEach((textMesh) => {
      if (!textMesh) return;
      if (typeof textMesh.dispose === 'function') {
        textMesh.dispose();
        return;
      }
      if (textMesh.geometry && typeof textMesh.geometry.dispose === 'function') {
        textMesh.geometry.dispose();
      }
      if (textMesh.material && typeof textMesh.material.dispose === 'function') {
        textMesh.material.dispose();
      }
    });

    disposables.lights.forEach((l) => {
      if (l && typeof l.dispose === 'function') l.dispose();
    });
  };

  return group;
}
